-- Bloomy — second seed: 54 products for Peekbox's six occasions, the six occasion tags, the occasion links of
-- the first 50 products, and (at the end) four more occasion campaigns with their coupons: Tết, Valentine,
-- Trung thu and Giáng sinh, next to the two in seed-reference.sql (20/10 and 20/11).
-- GENERATED by gen_products2.py, do not hand-edit row by row. Pricing as in the first seed (Nhỏ/Lớn are 70%/140% of
-- Vừa, stems 60%/150%); a bouquet costs its stems / 0.78 plus the style fee, a set about twice its stems.
--
-- ADDITIVE and IDEMPOTENT: no fixed ids; everything is looked up by SKU or by (kind, name); every INSERT ends in
-- ON CONFLICT DO NOTHING. So it loads after the first seed on a fresh database (seed.sh) AND runs on a live shop
-- (seed-more.sh): a second run changes nothing, and a product that already exists is never overwritten.
-- Must run AFTER seed-categories.sql, seed-flowers.sql and seed-products.sql (it needs the first 50 products), and
-- AFTER seed-reference.sql on a fresh database (that file inserts campaigns 1 and 2 with fixed ids; these four take the
-- next ones). seed.sh loads it last.
-- category_id: 1 sinh nhật, 2 cưới, 3 khai trương, 6 set quà tặng, 7 Tết, 8 mùa xuân, 10 mùa thu, 11 mùa đông.
-- Flower quantities are DRAFTS for the team to review, like the first seed's.

-- The occasions, in calendar order: their ids are the order the filter shows them in.
INSERT INTO tags (kind, name) VALUES
('occasion', 'Tết'),
('occasion', 'Valentine'),
('occasion', '8/3 và 20/10'),
('occasion', 'Trung thu'),
('occasion', '20/11'),
('occasion', 'Giáng sinh')
ON CONFLICT (kind, name) DO NOTHING;

INSERT INTO products (category_id, sku, name, short_description, description, image, status, featured, product_type, style, external_url) VALUES
(7, 'BLM-0052', 'Bó Mai Vàng Đón Xuân', 'Cành mai vàng, cúc vàng và hướng dương mini, rộn ràng đón xuân.', 'Cành mai vàng bung nở cùng cúc vàng và hướng dương mini — bó hoa Tết mang lộc đầu năm, rực rỡ cả gian nhà. Kèm lá măng và dây ruy băng đỏ.', 'images/bomaivangdonxuan.webp', 'available', false, 'standard', 'bo', NULL),
(7, 'BLM-0053', 'Bó Hồng Đỏ Phát Lộc', 'Hồng đỏ, cúc vàng và cành mai, chúc năm mới phát tài.', 'Hồng đỏ thắm kết hợp cúc vàng và cành mai — bó hoa Tết cầu mong một năm phát tài, phát lộc. Kèm lá bạc hà và giấy gói đỏ.', 'images/bohongdophatloc.webp', 'available', false, 'standard', 'bo', NULL),
(7, 'BLM-0054', 'Bó Cúc Vàng Cát Tường', 'Cúc vàng và cẩm chướng cam, tươi lâu suốt những ngày Tết.', 'Cúc vàng và cẩm chướng cam bền hoa — bó hoa Tết giản dị, giữ được màu tươi suốt những ngày đầu xuân. Kèm lá dương xỉ.', 'images/bocucvangcattuong.webp', 'available', false, 'standard', 'bo', NULL),
(7, 'BLM-0055', 'Bó Lan Đỏ Vạn Sự', 'Lan hồ điệp đỏ, cúc đỏ và cành mai, sang trọng ngày Tết.', 'Lan hồ điệp đỏ sang trọng đi cùng cúc đỏ và cành mai — bó hoa biếu Tết trang trọng, chúc vạn sự như ý. Kèm lá bạc hà và giấy gói kraft.', 'images/bolandovansu.webp', 'available', false, 'standard', 'bo', NULL),
(7, 'BLM-0056', 'Bó Hướng Dương Tài Lộc', 'Hướng dương, cúc vàng và cẩm chướng cam, ấm áp sắc xuân.', 'Hướng dương rực rỡ cùng cúc vàng và cẩm chướng cam — bó hoa Tết ấm áp, gửi lời chúc tài lộc đến mọi nhà. Kèm lá măng.', 'images/bohuongduongtailoc.webp', 'available', false, 'standard', 'bo', NULL),
(7, 'BLM-0057', 'Bó Cúc Đỏ Sum Vầy', 'Cúc đỏ và hồng đỏ, đỏ thắm cho bữa cơm sum vầy.', 'Cúc đỏ và hồng đỏ nổi bật trên bàn tiệc đoàn viên — bó hoa Tết đậm không khí sum vầy. Kèm lá bạc hà.', 'images/bocucdosumvay.webp', 'available', false, 'standard', 'bo', NULL),
(7, 'BLM-0058', 'Bó Mai Trắng Thanh Xuân', 'Cành mai, hồng trắng và cúc trắng, thanh nhã đầu năm.', 'Cành mai điểm cùng hồng trắng và cúc trắng — bó hoa Tết thanh nhã cho những ai thích một mùa xuân nhẹ nhàng. Kèm lá bạc hà và giấy gói trắng.', 'images/bomaitrangthanhxuan.webp', 'available', false, 'standard', 'bo', NULL),
(7, 'BLM-0059', 'Bó Hoa Tết Đoàn Viên', 'Hồng đỏ, hồng cam, cúc vàng và mai, đủ sắc cho nhà đông người.', 'Hồng đỏ, hồng cam, cúc vàng và cành mai gói chung một bó — đủ sắc màu cho ngôi nhà đông đủ con cháu ngày Tết. Kèm lá măng và giấy gói kraft.', 'images/bohoatetdoanvien.webp', 'available', false, 'standard', 'bo', NULL),
(7, 'BLM-0060', 'Bó Mẫu Đơn Phú Quý', 'Mẫu đơn hồng, hồng đỏ Pháp và cúc đỏ, phú quý đầu năm.', 'Mẫu đơn hồng đầy đặn cùng hồng đỏ Pháp và cúc đỏ — bó hoa Tết biếu tặng, mang ý nghĩa phú quý, sung túc. Kèm lá bạc hà và dây ruy băng vàng.', 'images/bomaudonphuquy.webp', 'available', false, 'standard', 'bo', NULL),
(7, 'BLM-0061', 'Bó Cúc Cam Hoàng Kim', 'Cúc cam, hướng dương mini và cành mai, vàng ấm như nắng xuân.', 'Cúc cam và hướng dương mini ấm như nắng xuân, thêm vài cành mai — bó hoa Tết tươi vui, hợp đặt phòng khách. Kèm lá măng.', 'images/bocuccamhoangkim.webp', 'available', false, 'standard', 'bo', NULL),
(1, 'BLM-0062', 'Bó Hồng Đỏ Say Đắm', 'Hồng đỏ Pháp nhung đỏ, đơn giản mà nồng nàn.', 'Những bông hồng đỏ Pháp nhung đỏ gói gọn trong một bó — cách nói yêu thương đơn giản và nồng nàn nhất. Kèm lá bạc hà và giấy gói đen.', 'images/bohongdosaydam.webp', 'available', false, 'standard', 'bo', NULL),
(1, 'BLM-0063', 'Bó Hồng Đỏ Trắng Giao Duyên', 'Hồng đỏ và hồng trắng đan xen, cho một mối duyên đẹp.', 'Hồng đỏ và hồng trắng đan xen trong cùng một bó — đối lập mà hòa hợp, như hai người dành cho nhau. Kèm lá bạc hà.', 'images/bohongdotranggiaoduyen.webp', 'available', false, 'standard', 'bo', NULL),
(1, 'BLM-0064', 'Bó Tulip Hồng Ngày Yêu', 'Tulip hồng và hồng peach, dịu dàng cho ngày lễ tình nhân.', 'Tulip hồng tươi mát cùng hồng peach ngọt ngào — bó hoa Valentine dịu dàng, cũng hợp tặng ngày 8/3. Kèm lá bạc hà.', 'images/botuliphongngayyeu.webp', 'available', false, 'standard', 'bo', NULL),
(1, 'BLM-0065', 'Bó Hồng Peony Đêm Valentine', 'Hồng peony, mẫu đơn hồng và hồng đỏ, lãng mạn và đầy đặn.', 'Hồng peony bung tròn cùng mẫu đơn hồng và hồng đỏ — một bó hoa Valentine đầy đặn, lãng mạn như bữa tối thắp nến. Kèm lá bạc hà và giấy gói kraft.', 'images/bohongpeonydemvalentine.webp', 'available', false, 'standard', 'bo', NULL),
(2, 'BLM-0066', 'Bó Hồng Cầu Hôn', 'Hồng đỏ Pháp và hoa sáp trắng, cho khoảnh khắc ngỏ lời.', 'Hồng đỏ Pháp điểm hoa sáp trắng — bó hoa cho khoảnh khắc quỳ gối ngỏ lời, trang trọng mà chân thành. Kèm lá bạc hà và dây ruy băng lụa.', 'images/bohongcauhon.webp', 'available', false, 'standard', 'bo', NULL),
(2, 'BLM-0067', 'Bó Hồng Mẫu Đơn Trọn Đời', 'Hồng đỏ Pháp, mẫu đơn hồng và hoa sáp, lời hẹn trọn đời.', 'Hồng đỏ Pháp, mẫu đơn hồng và hoa sáp trắng — bó hoa của lời hẹn ước, hợp cho kỷ niệm ngày cưới hay lễ đính hôn. Kèm lá bạc hà và giấy gói kem.', 'images/bohongmaudontrondoi.webp', 'available', false, 'standard', 'bo', NULL),
(2, 'BLM-0068', 'Bó Hồng Vintage Hẹn Ước', 'Hồng vintage và cẩm chướng hồng, màu cổ điển cho lời hẹn.', 'Hồng vintage tông trầm cùng cẩm chướng hồng — bó hoa màu cổ điển, nhẹ nhàng cho lời hẹn ước. Kèm lá bạc hà.', 'images/bohongvintagehenuoc.webp', 'available', false, 'standard', 'bo', NULL),
(6, 'BLM-0069', 'Hộp Hồng Đỏ Tình Yêu', 'Hồng đỏ xếp kín trong hộp tròn, tặng là nhớ.', 'Hồng đỏ xếp khít trong hộp tròn sang trọng — món quà Valentine gọn gàng, mở nắp ra là cả một mùa yêu. Kèm hộp tròn cứng và thiệp viết tay.', 'images/hophongdotinhyeu.webp', 'available', false, 'standard', 'hop', NULL),
(6, 'BLM-0070', 'Set Hồng & Socola Valentine', 'Hồng đỏ, hồng peach cùng hộp socola và thiệp.', 'Một bó hồng đỏ và hồng peach đi cùng hộp socola và thiệp viết tay — set quà Valentine đủ đầy, tặng là xong. Kèm hộp socola, thiệp viết tay và hộp quà.', 'images/setquahongsocolavalentine.webp', 'available', false, 'standard', 'set', NULL),
(6, 'BLM-0071', 'Set Hồng Đỏ & Gấu Bông', 'Hồng đỏ cùng gấu bông nhỏ và thiệp.', 'Bó hồng đỏ kèm một chú gấu bông nhỏ và tấm thiệp — set quà Valentine dễ thương, nhận là cười. Kèm gấu bông nhỏ, thiệp viết tay và hộp quà.', 'images/setquahongdogaubong.webp', 'available', false, 'standard', 'set', NULL),
(6, 'BLM-0072', 'Hộp Hồng Lavender Ngọt Ngào', 'Hồng lavender và hoa sáp trong hộp, tông tím ngọt ngào.', 'Hồng lavender điểm hoa sáp trắng trong hộp quà — tông tím ngọt ngào, khác biệt cho ngày lễ tình nhân. Kèm hộp vuông cứng và thiệp viết tay.', 'images/hophonglavenderngotngao.webp', 'available', false, 'standard', 'hop', NULL),
(1, 'BLM-0073', 'Bó Tulip Mừng 8/3', 'Tulip hồng và trắng, tươi mát mừng ngày Quốc tế Phụ nữ.', 'Tulip hồng và trắng tươi mát — bó hoa mừng ngày Quốc tế Phụ nữ, nhẹ nhàng và trang nhã. Kèm lá bạc hà.', 'images/botulipmung83.webp', 'available', false, 'standard', 'bo', NULL),
(1, 'BLM-0074', 'Bó Hồng Peach Ngày Của Nàng', 'Hồng peach và cẩm chướng hồng, ngọt ngào tặng nàng.', 'Hồng peach ngọt ngào cùng cẩm chướng hồng — bó hoa tặng người phụ nữ của bạn ngày 8/3 hoặc 20/10. Kèm lá bạc hà và giấy gói kraft.', 'images/bohongpeachngaycuanang.webp', 'available', false, 'standard', 'bo', NULL),
(1, 'BLM-0075', 'Bó Mẫu Đơn Tri Ân Phụ Nữ', 'Mẫu đơn hồng, hồng peony và cúc lavender, đầy đặn và ý nghĩa.', 'Mẫu đơn hồng, hồng peony và cúc lavender đầy đặn — bó hoa tri ân phụ nữ, trân trọng và sang trọng. Kèm lá bạc hà.', 'images/bomaudontriamphunu.webp', 'available', false, 'standard', 'bo', NULL),
(1, 'BLM-0076', 'Bó Hồng Pastel 20/10', 'Hồng peach, hồng lavender và hồng mini, tông pastel nhẹ.', 'Hồng peach, hồng lavender và hồng mini phối tông pastel — bó hoa 20/10 mềm mại, hợp mọi lứa tuổi. Kèm lá bạc hà.', 'images/bohongpastel2010.webp', 'available', false, 'standard', 'bo', NULL),
