(1, 'BLM-0085', 'Bó Hướng Dương Tri Ân Thầy Cô', 'Hướng dương và cúc vàng, lòng biết ơn rạng rỡ.', 'Hướng dương hướng về phía ánh sáng — như học trò luôn hướng về thầy cô. Kèm cúc vàng rạng rỡ. Kèm lá măng và thiệp cảm ơn.', 'images/bohuongduongtrianthayco.webp', 'available', false, 'standard', 'bo', NULL),
(1, 'BLM-0086', 'Bó Hoa Ly Kính Tặng Thầy Cô', 'Hoa ly trắng, cúc trắng và hoa sáp, trang nhã tôn kính.', 'Hoa ly trắng thanh cao cùng cúc trắng và hoa sáp — bó hoa trang nhã gửi đến người thầy, người cô đáng kính. Kèm lá dương xỉ và thiệp cảm ơn.', 'images/bohoalykinhtangthayco.webp', 'available', false, 'standard', 'bo', NULL),
(1, 'BLM-0087', 'Bó Cúc Vàng Ngày Nhà Giáo', 'Cúc vàng và hướng dương mini, tươi tắn ngày 20/11.', 'Cúc vàng và hướng dương mini tươi tắn — bó hoa đơn giản, dễ mang đến lớp hay đến nhà thầy cô. Kèm lá măng.', 'images/bocucvangngaynhagiao.webp', 'available', false, 'standard', 'bo', NULL),
(1, 'BLM-0088', 'Bó Hồng Cam Biết Ơn', 'Hồng cam và cúc cam, ấm áp lòng biết ơn.', 'Hồng cam và cúc cam ấm áp — bó hoa biết ơn gửi thầy cô, tông màu tươi và gần gũi. Kèm lá bạc hà và thiệp cảm ơn.', 'images/bohongcambietom.webp', 'available', false, 'standard', 'bo', NULL),
(1, 'BLM-0089', 'Bó Lan Vàng Kính Tặng Thầy', 'Lan hồ điệp vàng, cúc trắng và hoa sáp, trang trọng.', 'Lan hồ điệp vàng nổi bật giữa cúc trắng và hoa sáp — bó hoa trang trọng dành cho người thầy lớn tuổi. Kèm lá bạc hà và giấy gói kem.', 'images/bolanvangkinhtangthay.webp', 'available', false, 'standard', 'bo', NULL),
(6, 'BLM-0090', 'Set Quà Tri Ân Thầy Cô', 'Hướng dương, cúc vàng, sổ tay và thiệp tri ân.', 'Hướng dương và cúc vàng kèm một cuốn sổ tay và thiệp tri ân — set quà 20/11 thiết thực, thầy cô nào cũng dùng được. Kèm sổ tay, thiệp cảm ơn và hộp quà.', 'images/setquatrianthayco.webp', 'available', false, 'standard', 'set', NULL),
(6, 'BLM-0091', 'Hộp Hoa Hướng Dương Tặng Cô', 'Hướng dương và cẩm chướng cam trong hộp tròn.', 'Hướng dương và cẩm chướng cam xếp trong hộp tròn — món quà 20/11 tươi sáng, gọn nhẹ mang đến lớp. Kèm hộp tròn cứng và thiệp cảm ơn.', 'images/hophoahuongduongtangco.webp', 'available', false, 'standard', 'hop', NULL),
(6, 'BLM-0092', 'Set Quà Hoa & Trà 20/11', 'Cúc trắng, hồng trắng cùng hộp trà và thiệp.', 'Cúc trắng và hồng trắng đi cùng hộp trà và thiệp — set quà 20/11 thanh nhã, hợp thầy cô thích sự giản dị. Kèm hộp trà, thiệp cảm ơn và hộp quà.', 'images/setquahoatra2011.webp', 'available', false, 'standard', 'set', NULL),
(6, 'BLM-0093', 'Hộp Lan Hồ Điệp Tặng Thầy Cô', 'Lan hồ điệp vàng và cúc vàng trong hộp.', 'Lan hồ điệp vàng và cúc vàng trong hộp quà — món quà trang trọng, hoa nở lâu để thầy cô ngắm cả tháng. Kèm hộp vuông cứng và thiệp cảm ơn.', 'images/hoplanhodieptangthayco.webp', 'available', false, 'standard', 'hop', NULL),
(6, 'BLM-0094', 'Set Quà Hoa Tri Ân Nhẹ Nhàng', 'Cẩm chướng cam, hướng dương mini, socola và thiệp.', 'Cẩm chướng cam và hướng dương mini kèm hộp socola nhỏ — set quà 20/11 gọn nhẹ, vừa túi tiền cho cả lớp góp quà. Kèm hộp socola, thiệp cảm ơn và hộp quà.', 'images/setquahoatriannhenhang.webp', 'available', false, 'standard', 'set', NULL),
(10, 'BLM-0095', 'Bó Cúc Cam Trăng Rằm', 'Cúc cam và cúc vàng, ấm như ánh trăng rằm.', 'Cúc cam và cúc vàng ấm như ánh trăng rằm — bó hoa Trung thu để bàn cạnh mâm cỗ đoàn viên. Kèm lá măng.', 'images/bocuccamtrangram.webp', 'available', false, 'standard', 'bo', NULL),
(10, 'BLM-0096', 'Bó Hồng Cam Đêm Rằm', 'Hồng cam và cẩm chướng cam, ngọt như bánh nướng.', 'Hồng cam và cẩm chướng cam — sắc ấm của mùa thu, hợp tặng nhau bên hộp bánh trung thu. Kèm lá bạc hà và giấy gói kraft.', 'images/bohongcamdemram.webp', 'available', false, 'standard', 'bo', NULL),
(10, 'BLM-0097', 'Bó Hướng Dương Đoàn Viên Thu', 'Hướng dương, cúc cam và cúc vàng, rộn ràng ngày hội.', 'Hướng dương, cúc cam và cúc vàng — bó hoa rộn ràng cho đêm hội trăng rằm của cả nhà. Kèm lá măng.', 'images/bohuongduongdoanvienthu.webp', 'available', false, 'standard', 'bo', NULL),
(10, 'BLM-0098', 'Bó Cúc Trắng Ánh Trăng', 'Cúc trắng và hoa sáp, dịu như ánh trăng.', 'Cúc trắng và hoa sáp dịu như ánh trăng — bó hoa Trung thu thanh nhã, hợp tặng người lớn tuổi. Kèm lá bạc hà và giấy gói trắng.', 'images/bocuctranganhtrang.webp', 'available', false, 'standard', 'bo', NULL),
(10, 'BLM-0099', 'Bó Hoa Thu Ấm Áp Gia Đình', 'Hồng cam, cúc cam, hướng dương mini và cẩm chướng cam.', 'Hồng cam, cúc cam, hướng dương mini và cẩm chướng cam — đủ sắc ấm của mùa thu cho bàn tiệc cả gia đình. Kèm lá măng và giấy gói kraft.', 'images/bohoathuamapgiadinh.webp', 'available', false, 'standard', 'bo', NULL),
(11, 'BLM-0100', 'Bó Hồng Đỏ Giáng Sinh', 'Hồng đỏ và hồng trắng, đỏ trắng đúng màu Noel.', 'Hồng đỏ và hồng trắng — đúng hai màu của mùa Noel, đặt cạnh cây thông là đủ không khí lễ. Kèm lá bạc hà và dây ruy băng đỏ.', 'images/bohongdogiangsinh.webp', 'available', false, 'standard', 'bo', NULL),
(11, 'BLM-0101', 'Bó Hồng Trắng Noel Tuyết', 'Hồng trắng và hoa sáp, trắng như tuyết đầu mùa.', 'Hồng trắng và hoa sáp trắng muốt như tuyết đầu mùa — bó hoa Noel tinh khôi, nhẹ nhàng. Kèm lá bạc hà và giấy gói trắng.', 'images/bohongtrangnoeltuyet.webp', 'available', false, 'standard', 'bo', NULL),
(11, 'BLM-0102', 'Bó Hoa Noel Đỏ Trắng', 'Hồng đỏ, cẩm chướng trắng và hồng trắng.', 'Hồng đỏ, cẩm chướng trắng và hồng trắng gói chung — bó hoa Noel tươi, nổi bật trên bàn tiệc. Kèm lá bạc hà và dây ruy băng đỏ.', 'images/bohoanoeldotrang.webp', 'available', false, 'standard', 'bo', NULL),
(11, 'BLM-0103', 'Bó Mẫu Đơn Đông Ấm', 'Mẫu đơn hồng, hồng đỏ Pháp và cúc trắng, ấm cho mùa lạnh.', 'Mẫu đơn hồng, hồng đỏ Pháp và cúc trắng — bó hoa ấm áp, sang trọng cho mùa đông và những buổi tiệc cuối năm. Kèm lá bạc hà và giấy gói kem.', 'images/bomaudondongam.webp', 'available', false, 'standard', 'bo', NULL),
(11, 'BLM-0104', 'Bó Cúc Trắng Mùa Đông', 'Cúc trắng và hoa ly trắng, thanh khiết mùa đông.', 'Cúc trắng và hoa ly trắng thanh khiết — bó hoa mùa đông trang nhã, bền hoa trong tiết trời lạnh. Kèm lá dương xỉ và giấy gói trắng.', 'images/bocuctrangmuadong.webp', 'available', false, 'standard', 'bo', NULL),
(11, 'BLM-0105', 'Bó Hoa Noel Thanh Lịch', 'Hồng peony, hồng đỏ và hoa sáp trắng, sang trọng.', 'Hồng peony, hồng đỏ và hoa sáp trắng — bó hoa Noel thanh lịch để biếu hay tặng người thương. Kèm lá bạc hà và giấy gói kem.', 'images/bohoanoelthanhlich.webp', 'available', false, 'standard', 'bo', NULL)
ON CONFLICT (sku) DO NOTHING;

