-- A mistyped SKU or name would quietly add fewer rows; stop instead.
DO $$
BEGIN
  IF (SELECT count(*) FROM campaigns WHERE name IN ('Hoa đón Tết 2027', 'Valentine 14/2', 'Trung thu đoàn viên', 'Giáng sinh ấm áp')) <> 4 THEN
    RAISE EXCEPTION 'campaigns: expected the four new ones';
  END IF;
  IF (SELECT count(*) FROM campaign_products cp JOIN campaigns c ON c.id = cp.campaign_id WHERE c.name IN ('Hoa đón Tết 2027', 'Valentine 14/2', 'Trung thu đoàn viên', 'Giáng sinh ấm áp')) <> 24 THEN
    RAISE EXCEPTION 'campaign_products: expected 24 rows for the four new campaigns';
  END IF;
END $$;
